#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    int acc = 0; // use int for OpenMP reduction portability (bool reductions can be tricky)
    const std::size_t n = x.size();

    #pragma omp parallel for reduction(^:acc)
    for (std::size_t i = 0; i < n; ++i) {
        acc ^= static_cast<int>(x[i]);
    }

    return acc != 0;
}
